  var sids: [SidebarID] = [.root(project: p.id)]
  sids += p.workrooms.map { SidebarID.workroom(project: p.id, name: $0.name) }
  let worst = sids.compactMap { workroomStatuses[$0] }
    .max(by: { $0.aggregateWeight < $1.aggregateWeight })
  guard let worst, worst.aggregateWeight > 0 else { return nil }
  return worst
}

/// Run a PR write action (Phase 2b) on the selected workroom's PR: shell to `gh`, refresh the PR
/// on success, surface `stderr` on failure. In fixture mode it optimistically updates the seeded
/// status instead of spawning `gh`, so the actions menu is exercisable hermetically.
func performPRAction(_ action: PRAction, number: Int, on sid: SidebarID) {
  guard let item = selectedStatusWorkItem(for: sid) else { return }
  // Flip the PR state immediately so the badge/buttons react the instant the user acts — otherwise
  // nothing visibly changes during the (multi-second) `gh` call + status re-probe, which reads as
  // "the click did nothing". Keep the prior PR to restore if `gh` fails (and in fixture mode, this
  // optimistic update *is* the result — no `gh` to confirm it).
  let priorPR = workroomStatuses[sid]?.pr
  applyOptimisticPRAction(action, on: sid)
  if UITestFixture.isActive { return }
  prActionInFlight = true
  let resolver = statusResolver
  // Run `gh pr …` where the read probes run: in-place for git, but the colocated project root for
  // a jj workspace (gitless), else the action fails / targets the wrong repo context.
  let dir = WorkroomStatusResolver.ghProbeDirectory(
    path: item.path, vcs: item.vcs, projectRoot: item.projectRoot)
  Task { [weak self] in
    let r = await resolver.runPRCommand(action.arguments(number: number), in: dir)
    guard let self else { return }
    self.prActionInFlight = false
    if r.ok {
      // Re-probe to replace the optimistic state with GitHub's authoritative one.
      self.scheduleSelectedStatusRefresh()
    } else {
      // The command failed — undo the optimistic flip so the UI doesn't lie, then surface stderr.
      if var s = self.workroomStatuses[sid] {
        s.pr = priorPR
        self.workroomStatuses[sid] = s
      }
      self.errorTitle = "Couldn’t \(action.label.lowercased())"
      let stderr = r.stderr.trimmingCharacters(in: .whitespacesAndNewlines)
      self.errorMessage = stderr.isEmpty ? "The gh command failed." : stderr
    }
  }
}

/// Optimistically reflect a PR action in the in-memory status (no `gh`): the badge/state flip
/// immediately on click, before the command returns. The real path restores the prior PR if `gh`
/// fails and re-probes on success; fixture mode keeps this as the final result.
private func applyOptimisticPRAction(_ action: PRAction, on sid: SidebarID) {
  guard var s = workroomStatuses[sid], let pr = s.pr else { return }
  let state: PullRequestInfo.State
  let draft: Bool
  switch action {
  case .markReady:
    state = .open
    draft = false
  case .convertToDraft:
    state = .open
    draft = true
  case .close:
    state = .closed
    draft = pr.isDraft
  case .reopen:
    state = .open
    draft = pr.isDraft
  }
  // Carry the prior mergeability forward (the re-probe corrects it): dropping it here would flip
  // `canMerge` off and blink the Merge button away for the (multi-second) round-trip.
  s.pr = PullRequestInfo(
    number: pr.number, title: pr.title, state: state, isDraft: draft, url: pr.url,
    reviewDecision: pr.reviewDecision, reviewers: pr.reviewers,
    mergeable: pr.mergeable, mergeState: pr.mergeState)
  workroomStatuses[sid] = s
}

/// Merge the selected workroom's PR (issue #88) with `method`: shell to `gh pr merge`, refresh on
/// success, surface `stderr` on failure. Mirrors `performPRAction` — same in-flight gate, same
/// `gh` repo context, same optimistic-then-authoritative flow — but the strategy is a parameter,
/// so it's kept separate from the state-only `PRAction` verbs. In fixture mode it optimistically
/// flips the PR to merged instead of spawning `gh`.
func performMerge(_ method: PRMergeMethod, number: Int, on sid: SidebarID) {
  guard let item = selectedStatusWorkItem(for: sid) else { return }
  let priorPR = workroomStatuses[sid]?.pr
  applyOptimisticMerge(on: sid)
  if UITestFixture.isActive { return }
  prActionInFlight = true
  let resolver = statusResolver
  let dir = WorkroomStatusResolver.ghProbeDirectory(
    path: item.path, vcs: item.vcs, projectRoot: item.projectRoot)
  Task { [weak self] in
    let r = await resolver.runPRCommand(method.arguments(number: number), in: dir)
    guard let self else { return }
    self.prActionInFlight = false
    if r.ok {
      self.scheduleSelectedStatusRefresh()
    } else {
      if var s = self.workroomStatuses[sid] {
        s.pr = priorPR
        self.workroomStatuses[sid] = s
      }
      self.errorTitle = "Couldn’t merge pull request"
      let stderr = r.stderr.trimmingCharacters(in: .whitespacesAndNewlines)
      self.errorMessage = stderr.isEmpty ? "The gh command failed." : stderr
    }
  }
}

/// Optimistically flip the PR to merged (no `gh`): the badge turns purple and the Merge button
/// disappears the instant the user confirms. `mergeable` is cleared so `canMerge` is false too.
/// The real path restores the prior PR if `gh` fails and re-probes on success.
private func applyOptimisticMerge(on sid: SidebarID) {
  guard var s = workroomStatuses[sid], let pr = s.pr else { return }
  s.pr = PullRequestInfo(
    number: pr.number, title: pr.title, state: .merged, isDraft: false, url: pr.url,
    reviewDecision: pr.reviewDecision, reviewers: pr.reviewers,
    mergeable: false, mergeState: pr.mergeState)
  workroomStatuses[sid] = s
}

/// Seed deterministic VCS status for the UI-test fixture targets so the Changes inspector is
/// exercisable hermetically — the fixture paths aren't real repos, so the live probe would only
/// ever report "unknown". No-ops outside fixture mode.
func seedFixtureStatuses() {
  guard UITestFixture.isActive, let project = projects.first else { return }
  workroomStatuses[.root(project: project.path)] = UITestFixture.rootStatus
  if let workroom = project.workrooms.first {
    workroomStatuses[.workroom(project: project.path, name: workroom.name)] =
      UITestFixture.workroomStatus

import AppKit
import SwiftUI

/// The right inspector composed as a raw `NSSplitView` (horizontal dividers, panes stacked top to
/// bottom) instead of a SwiftUI `VStack`. Each section is one arranged subview: a **sticky header +
/// scrollable body** — the section header is a fixed `NSHostingController` at the top, the body
/// lives in a native `NSScrollView` below it, so a section scrolls its content when cramped (or
/// dragged small) without ever scrolling its own disclosure header out of view.
///
/// Sizing: the default distribution is **equal** among expanded panes (collapsed panes pinned to
/// the header), realised once via `setPosition(ofDividerAt:)`; thereafter the user drags dividers
/// freely (raw `NSSplitView` gives native drag + proportional window-resize) and a per-pane height
/// constraint enforces the floor / the collapsed pin.
///
/// Why a **raw** `NSSplitView` and not `NSSplitViewController`: the controller's `adjustSubviews`
/// hugs every pane to its content's fitting size and dumps the slack on the lowest-holding-priority
/// pane, overriding `setPosition` on every layout pass — so equal sizing is impossible there. A raw
/// split view only positions dividers and respects per-subview Auto Layout constraints; it never
/// hugs content. Why AppKit at all (vs the old SwiftUI `VStack`): it kills the header-title "swim"
/// (each header is its own stable hosting view; collapse moves *sibling* panes, not a per-frame
/// SwiftUI re-layout of a translating `Text`) and gives free system-preference auto-hiding scrollers
/// (a raw `NSScrollView` tracks "Show scroll bars").

// MARK: - Pane: sticky header + scrollable body

/// One split pane. The section header is a fixed-height `NSHostingController` pinned to the top; the
/// body sits below it in one of two hosting modes:
///
/// - **scroll** (default): the body is an `NSHostingController` (`.intrinsicContentSize`) inside a
///   vertically-scrolling `NSScrollView` — it reports its natural height and the AppKit scroll view
///   scrolls when the pane is shorter than the content (auto-hiding scrollers, tracks the system
///   "Show scroll bars" preference).
/// - **fill** (`fillsBody`): the body hosting view instead FILLS the pane below the header and is
///   expected to scroll ITSELF (a SwiftUI `ScrollView`). This bypasses the `.intrinsicContentSize` →
///   `NSScrollView` bridge, so an inline height animation inside the body (the History pane's
///   divergence expander) is driven entirely by SwiftUI and can't fight AppKit's scroll-container
///   resize-anchoring — the source of the visible content shift the bridge produced.
///
/// When collapsed, the body is hidden and the enclosing split pins the pane to the header height.
final class InspectorPaneViewController: NSViewController {
  private let headerHost = NSHostingController(rootView: AnyView(EmptyView()))
  private let bodyScroll = NSScrollView()
  private let bodyHost = NSHostingController(rootView: AnyView(EmptyView()))
  /// Whether the body fills the pane and scrolls itself (vs. the default `NSScrollView` hosting).
  /// Must be set before the view first loads.
  var fillsBody = false

  override func loadView() {
    let container = NSView()

    headerHost.view.translatesAutoresizingMaskIntoConstraints = false
    let bodyView: NSView

    if fillsBody {
      // Fill mode: the body hosting view fills below the header and owns its own scrolling.
      bodyHost.sizingOptions = []
      addChild(bodyHost)
      bodyView = bodyHost.view
      bodyView.translatesAutoresizingMaskIntoConstraints = false
      container.addSubview(bodyView)
    } else {
      // Scroll mode: the body scroll view is added FIRST, then the header, so the header is topmost
      // in z-order — the opaque sticky header always sits above the scrolling body so content can
      // never bleed over the title during a resize.
      bodyHost.sizingOptions = [.intrinsicContentSize]
      addChild(bodyHost)
      let document = bodyHost.view
      document.translatesAutoresizingMaskIntoConstraints = false
      bodyScroll.translatesAutoresizingMaskIntoConstraints = false
      bodyScroll.hasVerticalScroller = true
      bodyScroll.hasHorizontalScroller = false
      bodyScroll.autohidesScrollers = true
      bodyScroll.drawsBackground = false
      bodyScroll.documentView = document
      container.addSubview(bodyScroll)
      bodyView = bodyScroll
      NSLayoutConstraint.activate([
        // Document pinned to the clip view's top/width (free height → it grows to content and the
        // scroll view scrolls when the pane is shorter than the content).
        document.topAnchor.constraint(equalTo: bodyScroll.contentView.topAnchor),
        document.leadingAnchor.constraint(equalTo: bodyScroll.contentView.leadingAnchor),
        document.trailingAnchor.constraint(equalTo: bodyScroll.contentView.trailingAnchor),
        document.widthAnchor.constraint(equalTo: bodyScroll.contentView.widthAnchor),
      ])
    }

    addChild(headerHost)
    container.addSubview(headerHost.view)

    NSLayoutConstraint.activate([
      // Sticky header: fixed height at the top.
      headerHost.view.topAnchor.constraint(equalTo: container.topAnchor),
      headerHost.view.leadingAnchor.constraint(equalTo: container.leadingAnchor),
      headerHost.view.trailingAnchor.constraint(equalTo: container.trailingAnchor),
      headerHost.view.heightAnchor.constraint(equalToConstant: InspectorPanePolicy.headerHeight),

      // Body fills the rest of the pane below the header.
      bodyView.topAnchor.constraint(equalTo: headerHost.view.bottomAnchor),
      bodyView.leadingAnchor.constraint(equalTo: container.leadingAnchor),
      bodyView.trailingAnchor.constraint(equalTo: container.trailingAnchor),
      bodyView.bottomAnchor.constraint(equalTo: container.bottomAnchor),
    ])
    view = container
  }

  /// Swap the hosted header + body. The body is hidden when collapsed so only the header shows (the
  /// enclosing split also pins a collapsed pane to the header height).
  func setContent(header: AnyView, body: AnyView, collapsed: Bool) {
    _ = view  // ensure loaded
    headerHost.rootView = header
    bodyHost.rootView = body
    (fillsBody ? bodyHost.view : bodyScroll).isHidden = collapsed
  }
}

// MARK: - Split container

/// Owns the raw `NSSplitView` and the three pane child controllers. Sizing rules:
///
/// - A per-pane height constraint (swapped on collapse change) pins a collapsed pane to the header
///   and floors an expanded pane at `expandedMinHeight` — this is what a drag and a window resize
///   respect.
/// - The **default** distribution (equal among expanded panes, or the saved weights) is applied via
///   `setPosition` after the first real layout and on a workroom switch. Plain window resizes keep
///   the user's proportions (native `NSSplitView` behaviour).
/// - **Collapsing** a single section keeps the other panes' heights and flexes only a neighbour
///   (`reallocateOnToggle`), so a divider the user dragged between two unrelated sections survives a
///   collapse elsewhere. **Expanding** a section re-splits the expanded panes **equally**
///   (`allocate`) — re-opening a collapsed section returns the stack to equal heights (a third each
///   for Changes + History + Pull Request) rather than the minimum floor.
/// `NSSplitView` whose dividers use a themed hairline. The system's thin divider can render a hard,
/// near-black line between the section panes — most visible while the inspector collapses/expands —
/// so we override `dividerColor` to force our subtle border colour on every draw, mid-animation
/// included.
final class ThemedSplitView: NSSplitView {
  override var dividerColor: NSColor {
    ThemeService.shared.tokens.nsFg.withAlphaComponent(0.12)
  }
}

final class InspectorSplitContainerController: NSViewController, NSSplitViewDelegate {
  let splitView = ThemedSplitView()
  private(set) var panes: [InspectorPaneViewController] = []
  private var heightConstraints: [NSLayoutConstraint] = []
  // Sized to the installed pane count, which is dynamic: the active activity-bar section decides how
  // many sub-sections its pane stacks (3 for Changes + History + Pull Request, 1 for Files). Empty
  // until the first `install`.
  private var collapsedFlags: [Bool] = []
  private var weights: [CGFloat] = []
  private var workroomKey = ""

  /// What the next real layout should do. `.redistribute` re-derives the whole layout from the saved
  /// weights (initial layout + workroom switch); `.toggle` re-sizes for one collapse change while
  /// preserving the untouched panes' heights. Both need `bounds.height > 0`, so the work is deferred
  /// to `viewDidLayout`.
  private enum PendingLayout {
    case none
    case redistribute
    case toggle(index: Int, previous: [CGFloat])
  }

import AppKit
import Defaults
import SwiftUI

/// The right inspector (issue #24). macOS 14 supports only one `.inspector` per view, so the
/// inspector composes four collapsible sections — **Changes** (the selected workroom's VCS detail),
/// **History** (its commit log), **Files** (the repo tree), and **Pull Request** — rather than
/// separate inspectors. The toolbar `sidebar.right` toggle shows/hides the whole inspector; each
/// section's disclosure handles its own visibility (persisted). (Notifications moved to the left
/// sidebar, issue #118.)
struct RightInspector: View {
  @EnvironmentObject var store: AppStore
  @EnvironmentObject var notifications: NotificationCenterStore
  @Environment(\.openURL) private var openURL
  /// A PR action awaiting confirmation (close), surfaced via a confirmation dialog.
  @State private var pendingConfirm: PendingPRAction?

  var body: some View {
    // The active activity-bar section decides which sub-sections this pane stacks (Changes stacks
    // Changes + History + Pull Request; Files is solo). Each sub-section's header + body are handed
    // to the NSSplitView bridge (see InspectorSplitView) as environment-injected AnyViews — the tree
    // does NOT inherit our `@EnvironmentObject`s across NSHostingController. Collapse flags +
    // size-weights persist as full `InspectorSectionKind.allCases`-ordered vectors on the store; we
    // slice out — and write back — the entries for the sub-sections actually shown, by `storeIndex`.
    let subs = store.activeInspectorSection.subSections
    VStack(spacing: 0) {
      // The VCS toolbar sits ABOVE the section stack, not inside a section, so it survives a collapsed
      // Changes section. Only for the Changes activity section: branch/remote state is what that section
      // is about, and showing it over the Files tree would jump the layout on every activity-bar click.
      if store.activeInspectorSection == .changes {
        VCSToolbar(model: store.remoteState)
      }
      inspectorSplit(subs: subs)
    }
    // Bound to the STORE, not a local `@State`: the gate that raises this lives in
    // `AppStore.performRemoteAction` so the Source Control menu's ⌥⇧⌘P goes through it too. When the
    // toolbar owned the gate, the shortcut autostashed a dirty tree with no warning at all.
    .confirmationDialog(
      store.pendingRemoteConfirm.map { "\($0.action.label) with uncommitted changes?" } ?? "",
      isPresented: Binding(
        get: { store.pendingRemoteConfirm != nil },
        set: { if !$0 { store.pendingRemoteConfirm = nil } }),
      presenting: store.pendingRemoteConfirm
    ) { item in
      // `runRemoteAction(on:)`, which re-checks `item.sid` — the dialog isn't modal to the sidebar, so
      // the selection can move while it's open and `performRemoteAction` would re-derive the target.
      Button(item.action.label) { store.runRemoteAction(item.action, on: item.sid) }
      Button("Cancel", role: .cancel) {}
    } message: { _ in
      Text("Your uncommitted changes will be stashed and reapplied after the rebase.")
    }
  }

  @ViewBuilder private func inspectorSplit(subs: [InspectorSectionKind]) -> some View {
    InspectorSplitView(
      headers: subs.map { sectionHeader(for: $0) },
      bodies: subs.map { sectionBody(for: $0) },
      collapsed: subs.map { collapsedValue(for: $0) },
      // History hosts its body in fill mode (it scrolls itself via SwiftUI) so its divergence
      // expander animates cleanly; the other sections keep the default NSScrollView hosting.
      fills: subs.map { $0 == .history },
      sectionKey: store.activeInspectorSection.rawValue,
      // The section layout is GLOBAL, not per-workroom, so this key is constant: switching workrooms
      // must not trigger the controller's workroom-switch redistribute (only a section change, via
      // `sectionKey`, or a genuine collapse/drag re-lays out the panes).
      workroomKey: "global",
      weights: subs.map { store.inspectorSizeWeights[$0.storeIndex] },
      onWeightsChanged: { shown in
        var full = store.inspectorSizeWeights
        for (index, sub) in subs.enumerated() where index < shown.count {
          full[sub.storeIndex] = shown[index]
        }
        store.updateInspectorSizeWeights(full)
      }
    )
    .frame(minWidth: 260, maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
    .confirmationDialog(
      pendingConfirm.map { "\($0.action.label)?" } ?? "",
      isPresented: Binding(
        get: { pendingConfirm != nil }, set: { if !$0 { pendingConfirm = nil } }),
      presenting: pendingConfirm
    ) { item in
      Button(item.action.label, role: .destructive) {
        store.performPRAction(item.action, number: item.number, on: item.sid)
      }
      Button("Cancel", role: .cancel) {}
    }
  }

  /// The live collapse value for a sub-section. A solo pane (Files, which stacks only itself) never
  /// collapses, so it reports expanded and its header shows no chevron.
  private func collapsedValue(for sub: InspectorSectionKind) -> Bool {
    switch sub {
    case .changes: return store.changesSectionCollapsed
    case .files: return false
    case .pullRequest: return store.prSectionCollapsed
    case .history: return store.historySectionCollapsed
    }
  }

  /// A sub-section's sticky header, environment-injected for the NSHostingController-hosted tree.
  /// Files passes a nil collapse binding (solo pane → no chevron).
  private func sectionHeader(for sub: InspectorSectionKind) -> AnyView {
    switch sub {
    case .changes:
      return AnyView(
        SectionHeader(
          title: "Changes", collapsed: $store.changesSectionCollapsed,
          indicator: changesIndicator, indicatorLabel: changesIndicatorLabel, shortcut: "⌥⌘C"
        ) {
          InspectorHeaderButton(systemImage: "arrow.clockwise", help: "Refresh workroom status") {
            store.refreshWorkroomStatuses(force: true)
          }
        }
        .environmentObject(store).environmentObject(notifications))
    case .files:
      return AnyView(
        SectionHeader(title: "Files", collapsed: nil, shortcut: "⌥⌘F") {
          InspectorHeaderButton(systemImage: "arrow.clockwise", help: "Refresh files") {
            store.fileTree.reload()
          }
        }
        .environmentObject(store).environmentObject(notifications))
    case .pullRequest:
      return AnyView(
        SectionHeader(title: "Pull Request", collapsed: $store.prSectionCollapsed, shortcut: "⌥⌘P")
        {
          prHeaderAccessory
        }
        .environmentObject(store).environmentObject(notifications))
    case .history:
      return AnyView(
        SectionHeader(
          title: "History", collapsed: $store.historySectionCollapsed, shortcut: "⌥⌘Y"
        ) {
          // Disabled while collapsed: a collapsed section deliberately stops tracking the selection
          // (`historySectionShown` gates the re-point), so the model still points at whatever workroom
          // was selected when it shut — clicking Refresh there would read THAT repo's log, not the
          // selected one, for a list nobody can see. Expanding re-points first, then loads.
          InspectorHeaderButton(
            systemImage: "arrow.clockwise", help: "Refresh history",
            disabled: store.historySectionCollapsed
          ) {
            store.commitHistory.refresh()
          }
        }
        .environmentObject(store).environmentObject(notifications))
    }
  }

  /// A sub-section's scrollable body, environment-injected for the hosted tree.
  private func sectionBody(for sub: InspectorSectionKind) -> AnyView {
    switch sub {
    case .changes:
      return AnyView(ChangesPanel().environmentObject(store).environmentObject(notifications))
    case .files:
      return AnyView(
        FilesPanel(model: store.fileTree).environmentObject(store).environmentObject(notifications))
    case .pullRequest:
      return AnyView(PullRequestPanel().environmentObject(store).environmentObject(notifications))

