            VcsError::UnsupportedRepo(format!("no jj repo at {}", path.display()))
        }
        WorkspaceLoadError::RepoDoesNotExist(path) => {
            VcsError::UnsupportedRepo(format!("jj repo no longer at {}", path.display()))
