1	//! The user's real jj configuration, instead of jj-lib's built-in defaults.
2	//!
3	//! **Why this exists.** Every entry point here used to build settings from
4	//! `StackedConfig::with_defaults()`, whose compiled-in `misc.toml` sets `user.name = ""`,
5	//! `user.email = ""` and `signing.backend = "none"`. That is not a cosmetic gap on the one code path
6	//! that *writes*:
7	//!
8	//! - `snapshot_working_copy` rewrites `@` whenever the working copy has moved, and jj-lib's
9	//!   `CommitBuilder::for_rewrite_from` unconditionally sets `commit.committer = settings.signature()`.
10	//!   With defaults-only settings that stamps an **empty committer name and email** onto the working
11	//!   copy commit — for every jj user, on every status refresh that finds a change. It is usually
12	//!   invisible (`jj log` shows the author) and self-heals on the next real `jj` command, but it does
13	//!   NOT heal if `@` is pushed as-is, which the app's own Push button does via `jj git push --change @`.
14	//! - `Signer::from_settings` reads `signing.backend` from the same settings, so `can_sign()` is false
15	//!   and `write_to_store` sets `secure_sig = None`. Under the default `behavior = "keep"` that means
16	//!   rewriting an already-signed `@` silently **drops its signature**.
17	//!
18	//! **jj-lib does no discovery.** It supplies the primitives (`ConfigLayer::load_from_file`,
19	//! `StackedConfig::add_layer`, the `ConfigSource` precedence order) and nothing else — locating the
20	//! files is jj-*cli*'s job, and jj-cli is not vendored. So the chain below is ours, and it mirrors
21	//! what `jj config path --user` reports.
22	//!
23	//! **Best-effort by design.** A layer that cannot be read or parsed is skipped rather than failing
24	//! the call. A malformed `~/.config/jj/config.toml` should cost the user their customisations, not
25	//! their Changes panel — degrading to jj's defaults is exactly what this module already did for
26	//! everyone before it existed.
27	
28	use std::path::{Path, PathBuf};
29	
30	use jj_lib::config::{ConfigLayer, ConfigSource, StackedConfig};
31	use jj_lib::settings::UserSettings;
32	
33	use wr_vcs_model as model;
34	use wr_vcs_model::VcsError;
35	
36	/// The environment the config chain is resolved against.
37	///
38	/// A struct rather than direct `std::env` reads so the whole path policy is unit-testable: cargo
39	/// runs tests as parallel threads of ONE process, so a test that mutated the real environment would
40	/// be visible to — and racing with — every other test in the binary.
41	#[derive(Debug, Default, Clone)]
42	pub(crate) struct ConfigEnv {
43	    pub jj_config: Option<PathBuf>,
44	    pub home: Option<PathBuf>,
45	    pub xdg_config_home: Option<PathBuf>,
46	}
47	
48	impl ConfigEnv {
49	    pub(crate) fn from_process() -> Self {
50	        Self {
51	            jj_config: std::env::var_os("JJ_CONFIG").map(PathBuf::from),
52	            home: std::env::var_os("HOME").map(PathBuf::from),
53	            xdg_config_home: std::env::var_os("XDG_CONFIG_HOME").map(PathBuf::from),
54	        }
55	    }
56	}
57	
58	/// The config files to layer, **lowest precedence first**.
59	///
60	/// `JJ_CONFIG` REPLACES the default locations rather than adding to them — that is jj's own
61	/// behaviour, and it is what makes the variable usable for isolation (the integration fixtures here
62	/// rely on it). It may name a file or a directory of `*.toml`.
63	///
64	/// Otherwise the two documented user locations are both collected, in the order jj's own precedence
65	/// implies. Merging them rather than picking one is a deliberate simplification: in practice exactly
66	/// one exists, and if somebody has both, honouring both in a defined order is friendlier than
67	/// silently ignoring whichever we didn't guess.
68	///
69	/// Verified against `jj config path --user` on macOS with jj 0.43 — it answers
70	/// `~/.config/jj/config.toml`, i.e. the XDG location, NOT `~/Library/Application Support`.
71	pub(crate) fn config_paths(env: &ConfigEnv) -> Vec<PathBuf> {
72	    if let Some(explicit) = &env.jj_config {
73	        return toml_files_at(explicit);
74	    }
75	    let mut paths = Vec::new();
76	    if let Some(home) = &env.home {
77	        paths.extend(toml_files_at(&home.join(".jjconfig.toml")));
78	    }
79	    let config_home = env
80	        .xdg_config_home
81	        .clone()
82	        .or_else(|| env.home.as_ref().map(|h| h.join(".config")));
83	    if let Some(dir) = config_home {
84	        paths.extend(toml_files_at(&dir.join("jj").join("config.toml")));
85	        // `conf.d` is jj's drop-in directory, layered above the single file.
86	        paths.extend(toml_files_at(&dir.join("jj").join("conf.d")));
87	    }
88	    paths
89	}
90	
91	/// The `*.toml` files at `path`: the file itself, or every `*.toml` directly inside it, sorted.
92	///
93	/// Sorted because a drop-in directory's precedence has to be reproducible — an unsorted `read_dir`
94	/// returns entries in filesystem order, so two machines with the same `conf.d` could resolve the
95	/// same key differently. Non-recursive, matching jj-lib's own (private) `load_from_dir`.
96	fn toml_files_at(path: &Path) -> Vec<PathBuf> {
97	    if path.is_file() {
98	        return vec![path.to_path_buf()];
99	    }
100	    if !path.is_dir() {
101	        return Vec::new();
102	    }
103	    let Ok(entries) = std::fs::read_dir(path) else {
104	        return Vec::new();
105	    };
106	    let mut files: Vec<PathBuf> = entries
107	        .filter_map(|entry| entry.ok().map(|e| e.path()))
108	        .filter(|p| p.is_file() && p.extension().is_some_and(|ext| ext == "toml"))
109	        .collect();
110	    files.sort();
111	    files
112	}
113	
114	/// jj's built-in defaults with the user's own configuration layered on top.
115	pub(crate) fn user_settings_for(env: &ConfigEnv) -> model::Result<UserSettings> {
116	    let mut config = StackedConfig::with_defaults();
117	    for path in config_paths(env) {
118	        // Skipped, not propagated — see the module comment. A broken config file costs the user
119	        // their settings, never their ability to read the repo.
120	        if let Ok(layer) = ConfigLayer::load_from_file(ConfigSource::User, path) {
121	            config.add_layer(layer);
122	        }
123	    }
124	    UserSettings::from_config(config).map_err(|e| VcsError::Io(e.to_string()))
125	}
