/// **What only this tier can see.** `VCSCommitIntegrationTests` proves what git and jj actually do,
/// but it drives `CLIVCSWriter` directly and never renders anything. Everything below is about the
/// path between a click and a `VCSCommitRequest` — which button is live, what the label claims, which
/// controls exist per backend, and whether a failure survives to the screen. `FixtureVCSWriter`
/// answers the write, so no real repo is touched.
///
/// Run with `make app-uitest` on a real GUI login session — XCUITest can't drive a headless run, so
/// these live in a separate scheme, excluded from `make app-test`.
final class CommitSheetUITests: XCTestCase {
  override func setUpWithError() throws { continueAfterFailure = false }

  private func launchedApp(extraArguments: [String] = []) -> XCUIApplication {
    let app = XCUIApplication()
    app.launchArguments += ["-WorkroomUITestFixture", "1"]
    app.launchArguments += ["-ApplePersistenceIgnoreState", "YES"]
    app.launchArguments += extraArguments
    app.launch()
    app.activate()
    return app
  }

  private func element(_ app: XCUIApplication, id: String) -> XCUIElement {
    app.descendants(matching: .any).matching(identifier: id).firstMatch
  }

  /// A clickable control, scoped to `.button`.
  ///
  /// Not `descendants(matching: .any)`: that resolves to whichever element carries the identifier
  /// first, which can be a container rather than the control — clicking it then lands on the
  /// container's centre and silently does nothing, which is exactly how the checkbox failure
  /// presented (the count never moved and no assertion pointed at the cause).
  private func button(_ app: XCUIApplication, id: String) -> XCUIElement {
    app.buttons.matching(identifier: id).firstMatch
  }

  /// Open the dialog from the Changes section header and wait for it.
  @discardableResult
  private func openSheet(_ app: XCUIApplication) -> XCUIElement {
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
    XCTAssertTrue(
      element(app, id: "inspector.header.Changes").waitForExistence(timeout: 10),
      "the Changes section should exist")
    let open = button(app, id: "changes.commitButton")
    XCTAssertTrue(open.waitForExistence(timeout: 10), "the Changes header should offer Commit")
    open.click()
    let sheet = element(app, id: "commit.sheet")
    XCTAssertTrue(sheet.waitForExistence(timeout: 10), "the commit dialog should open")
    return sheet
  }

  private func typeSummary(_ app: XCUIApplication, _ text: String) {
    let field = element(app, id: "commit.summary")
    XCTAssertTrue(field.waitForExistence(timeout: 5), "the summary field should exist")
    field.click()
    field.typeText(text)
  }

  // MARK: - git

  /// The whole point of the dialog: it names what it is about to record, per file, before you commit.
  func testGitSheetListsFilesWithCheckboxes() throws {
    let app = launchedApp(extraArguments: ["-WorkroomUITestGitWorkroom", "1"])
    openSheet(app)

    XCTAssertTrue(
      button(app, id: "commit.file.check.Gemfile").waitForExistence(timeout: 5),
      "a git file row should carry an inclusion checkbox")
    XCTAssertTrue(
      button(app, id: "commit.selectAll").exists, "and a bulk select-all affordance")
  }

  /// A blocked state must be readable, not hidden in a tooltip nobody hovers on a dead-looking
  /// button — so the reason renders as its own element and Commit is genuinely disabled.
  func testCommitIsBlockedUntilThereIsASummary() throws {
    let app = launchedApp(extraArguments: ["-WorkroomUITestGitWorkroom", "1"])
    openSheet(app)

    let blocked = element(app, id: "commit.blocked")
    XCTAssertTrue(blocked.waitForExistence(timeout: 5), "the reason should be stated on screen")
    XCTAssertTrue(
      (blocked.label + blocked.value.debugDescription).contains("summary"),
      "and should name the missing summary, got: \(blocked.label)")

    let commit = button(app, id: "commit.commit")
    XCTAssertTrue(commit.exists)
    XCTAssertFalse(commit.isEnabled, "Commit stays disabled with no summary")

    typeSummary(app, "Add session login")
    let enabled = NSPredicate(format: "isEnabled == true")
    XCTAssertEqual(
      XCTWaiter().wait(
        for: [XCTNSPredicateExpectation(predicate: enabled, object: commit)], timeout: 5),
      .completed, "typing a summary should enable Commit")
  }

  /// The count is the honest claim about what will be recorded, so it has to track the checkboxes —
  /// once the list scrolls, the label is the only thing the user can verify against.
  func testDeselectingAFileChangesTheCommitCount() throws {
    let app = launchedApp(extraArguments: ["-WorkroomUITestGitWorkroom", "1"])
    openSheet(app)
    typeSummary(app, "Add session login")

    let commit = button(app, id: "commit.commit")
    XCTAssertTrue(commit.waitForExistence(timeout: 5))
    let before = commit.label
    XCTAssertTrue(before.contains("file"), "the label should name a count, got: \(before)")

    button(app, id: "commit.file.check.Gemfile").click()

    let changed = NSPredicate(format: "label != %@", before)
    XCTAssertEqual(
      XCTWaiter().wait(
        for: [XCTNSPredicateExpectation(predicate: changed, object: commit)], timeout: 5),
      .completed, "excluding a file should change the count, still read: \(commit.label)")
  }

  /// Select-all is what makes "commit only this file" cheap; without it that intent costs one click
  /// per unwanted file.
  func testSelectAllTogglesEveryFile() throws {
    let app = launchedApp(extraArguments: ["-WorkroomUITestGitWorkroom", "1"])
    openSheet(app)
    typeSummary(app, "Add session login")

    let commit = button(app, id: "commit.commit")
    XCTAssertTrue(commit.waitForExistence(timeout: 5))
    button(app, id: "commit.selectAll").click()

    // Everything excluded ⇒ nothing to commit, which is a blocked state with its own message.
    let blocked = element(app, id: "commit.blocked")
    XCTAssertTrue(
      blocked.waitForExistence(timeout: 5), "deselecting everything should block the commit")
    XCTAssertFalse(commit.isEnabled, "and Commit should not be live with nothing selected")
  }

  // MARK: - jj

  /// jj has no index and commits the whole change, so rendering checkboxes whose only effect would be
  /// to disable the button is a designed dead end.
  func testJJSheetOffersNoPerFileSelection() throws {
    // `-WorkroomUITestJJProject` is the flag that matters: the fixture's PROJECT declares `vcs: "git"`
    // by default and only this makes it jj. `-WorkroomUITestGitWorkroom` changes the status SHAPE
    // (whether `jjWorkingCopy` is populated), not the backend the sheet resolves — so without this the
    // sheet correctly rendered git checkboxes and the test was asserting against the wrong backend.
    let app = launchedApp(extraArguments: ["-WorkroomUITestJJProject", "1"])
    openSheet(app)

    XCTAssertTrue(
      element(app, id: "commit.summary").waitForExistence(timeout: 5), "the sheet should render")
    XCTAssertFalse(
      button(app, id: "commit.file.check.Gemfile").exists,
      "jj must not offer per-file checkboxes")
    XCTAssertFalse(
      button(app, id: "commit.selectAll").exists, "nor a select-all for a selection it can't make")
  }

  /// Each backend's second verb is its own named button, not a menu item. A menu holding exactly one
  /// entry costs a click and leaves the control unnamed until it's opened.
  func testGitOffersAmendAsItsOwnButton() throws {
    let app = launchedApp(extraArguments: ["-WorkroomUITestGitWorkroom", "1"])
    openSheet(app)

    let amend = button(app, id: "commit.amend")
    XCTAssertTrue(amend.waitForExistence(timeout: 5), "git should offer Amend directly")
    XCTAssertEqual(amend.label, "Amend last commit")
    XCTAssertFalse(
      button(app, id: "commit.describe").exists, "and never jj's verb")

    // Amend rewords the last commit, so it needs a message just as Commit does.
    XCTAssertFalse(amend.isEnabled, "no summary yet")
    typeSummary(app, "Reworded")
    let enabled = NSPredicate(format: "isEnabled == true")
    XCTAssertEqual(
      XCTWaiter().wait(
        for: [XCTNSPredicateExpectation(predicate: enabled, object: amend)], timeout: 5),
      .completed)
  }

  func testJJOffersDescribeAsItsOwnButton() throws {
    let app = launchedApp(extraArguments: ["-WorkroomUITestJJProject", "1"])
    openSheet(app)

    let describe = button(app, id: "commit.describe")
    XCTAssertTrue(describe.waitForExistence(timeout: 5), "jj should offer Describe directly")
    XCTAssertEqual(describe.label, "Describe")
    XCTAssertFalse(
      button(app, id: "commit.amend").exists, "jj has no amend — it must not be offered")
  }

  // MARK: - Failure

  /// The defining moment. A hook's output is the most useful text in the whole taxonomy, so a
  /// rejected commit must keep the dialog open, keep the draft, and still carry the output.
  func testARejectedCommitKeepsTheSheetAndTheHookOutput() throws {
    let app = launchedApp(
      extraArguments: ["-WorkroomUITestGitWorkroom", "1", "-WorkroomUITestSyncFailure", "1"])
    openSheet(app)
    typeSummary(app, "Add session login")

    button(app, id: "commit.commit").click()

    // The fixture writer delays deliberately so the in-flight state is observable rather than
    // instantaneous, hence the generous timeout.
    XCTAssertTrue(
      element(app, id: "commit.failure").waitForExistence(timeout: 20),
      "a rejected commit should report itself in the dialog")
    XCTAssertTrue(
      element(app, id: "commit.sheet").exists, "and the dialog must stay open, draft intact")
    XCTAssertTrue(
      element(app, id: "commit.summary").exists, "the typed summary is not thrown away")
    XCTAssertTrue(
      element(app, id: "commit.failure.detailsToggle").exists,
      "the hook's own output must be reachable, not flattened to one line")
  }

  // MARK: - Success and dismissal

  /// A successful commit closes the dialog — the Changes list becoming clean is the confirmation.
  func testASuccessfulCommitClosesTheSheet() throws {
    let app = launchedApp(extraArguments: ["-WorkroomUITestGitWorkroom", "1"])
    openSheet(app)
    typeSummary(app, "Add session login")

    button(app, id: "commit.commit").click()

    let sheet = element(app, id: "commit.sheet")
    let gone = NSPredicate(format: "exists == false")
    XCTAssertEqual(
      XCTWaiter().wait(
        for: [XCTNSPredicateExpectation(predicate: gone, object: sheet)], timeout: 20),
      .completed, "the dialog should close once the commit lands")
  }

  func testCancelClosesTheSheetWithoutCommitting() throws {
    let app = launchedApp(extraArguments: ["-WorkroomUITestGitWorkroom", "1"])
    openSheet(app)

    button(app, id: "commit.cancel").click()

    let sheet = element(app, id: "commit.sheet")
    let gone = NSPredicate(format: "exists == false")
    XCTAssertEqual(
      XCTWaiter().wait(
        for: [XCTNSPredicateExpectation(predicate: gone, object: sheet)], timeout: 5),
      .completed, "Cancel should dismiss the dialog")
  }
}

//! The user's real jj configuration, instead of jj-lib's built-in defaults.
//!
//! **Why this exists.** Every entry point here used to build settings from
//! `StackedConfig::with_defaults()`, whose compiled-in `misc.toml` sets `user.name = ""`,
//! `user.email = ""` and `signing.backend = "none"`. That is not a cosmetic gap on the one code path
//! that *writes*:
//!
//! - `snapshot_working_copy` rewrites `@` whenever the working copy has moved, and jj-lib's
//!   `CommitBuilder::for_rewrite_from` unconditionally sets `commit.committer = settings.signature()`.
//!   With defaults-only settings that stamps an **empty committer name and email** onto the working
//!   copy commit — for every jj user, on every status refresh that finds a change. It is usually
//!   invisible (`jj log` shows the author) and self-heals on the next real `jj` command, but it does
//!   NOT heal if `@` is pushed as-is, which the app's own Push button does via `jj git push --change @`.
//! - `Signer::from_settings` reads `signing.backend` from the same settings, so `can_sign()` is false
//!   and `write_to_store` sets `secure_sig = None`. Under the default `behavior = "keep"` that means
//!   rewriting an already-signed `@` silently **drops its signature**.
//!
//! **jj-lib does no discovery.** It supplies the primitives (`ConfigLayer::load_from_file`,
//! `StackedConfig::add_layer`, the `ConfigSource` precedence order) and nothing else — locating the
//! files is jj-*cli*'s job, and jj-cli is not vendored. So the chain below is ours, and it mirrors
//! what `jj config path --user` reports.
//!
//! **Best-effort by design.** A layer that cannot be read or parsed is skipped rather than failing
//! the call. A malformed `~/.config/jj/config.toml` should cost the user their customisations, not
//! their Changes panel — degrading to jj's defaults is exactly what this module already did for
//! everyone before it existed.

use std::path::{Path, PathBuf};

use jj_lib::config::{ConfigLayer, ConfigSource, StackedConfig};
use jj_lib::settings::UserSettings;

use wr_vcs_model as model;
use wr_vcs_model::VcsError;

/// The environment the config chain is resolved against.
///
/// A struct rather than direct `std::env` reads so the whole path policy is unit-testable: cargo
/// runs tests as parallel threads of ONE process, so a test that mutated the real environment would
/// be visible to — and racing with — every other test in the binary.
#[derive(Debug, Default, Clone)]
pub(crate) struct ConfigEnv {
    pub jj_config: Option<PathBuf>,
    pub home: Option<PathBuf>,
    pub xdg_config_home: Option<PathBuf>,
}

impl ConfigEnv {
    pub(crate) fn from_process() -> Self {
        Self {
            jj_config: std::env::var_os("JJ_CONFIG").map(PathBuf::from),
            home: std::env::var_os("HOME").map(PathBuf::from),
            xdg_config_home: std::env::var_os("XDG_CONFIG_HOME").map(PathBuf::from),
        }
    }
}

/// The config files to layer, **lowest precedence first**.
///
/// `JJ_CONFIG` REPLACES the default locations rather than adding to them — that is jj's own
/// behaviour, and it is what makes the variable usable for isolation (the integration fixtures here
/// rely on it). It may name a file or a directory of `*.toml`.
///
/// Otherwise the two documented user locations are both collected, in the order jj's own precedence
/// implies. Merging them rather than picking one is a deliberate simplification: in practice exactly
/// one exists, and if somebody has both, honouring both in a defined order is friendlier than
/// silently ignoring whichever we didn't guess.
///
/// Verified against `jj config path --user` on macOS with jj 0.43 — it answers
/// `~/.config/jj/config.toml`, i.e. the XDG location, NOT `~/Library/Application Support`.
pub(crate) fn config_paths(env: &ConfigEnv) -> Vec<PathBuf> {
    if let Some(explicit) = &env.jj_config {
        return toml_files_at(explicit);
    }
    let mut paths = Vec::new();
    if let Some(home) = &env.home {
        paths.extend(toml_files_at(&home.join(".jjconfig.toml")));
    }
    let config_home = env
        .xdg_config_home
        .clone()
        .or_else(|| env.home.as_ref().map(|h| h.join(".config")));
    if let Some(dir) = config_home {
        paths.extend(toml_files_at(&dir.join("jj").join("config.toml")));
        // `conf.d` is jj's drop-in directory, layered above the single file.
        paths.extend(toml_files_at(&dir.join("jj").join("conf.d")));
    }
    paths
}

/// The `*.toml` files at `path`: the file itself, or every `*.toml` directly inside it, sorted.
///
/// Sorted because a drop-in directory's precedence has to be reproducible — an unsorted `read_dir`
/// returns entries in filesystem order, so two machines with the same `conf.d` could resolve the
/// same key differently. Non-recursive, matching jj-lib's own (private) `load_from_dir`.
fn toml_files_at(path: &Path) -> Vec<PathBuf> {
    if path.is_file() {
        return vec![path.to_path_buf()];
    }
    if !path.is_dir() {
        return Vec::new();
    }
    let Ok(entries) = std::fs::read_dir(path) else {
        return Vec::new();
    };
    let mut files: Vec<PathBuf> = entries
        .filter_map(|entry| entry.ok().map(|e| e.path()))
        .filter(|p| p.is_file() && p.extension().is_some_and(|ext| ext == "toml"))
        .collect();
    files.sort();
    files
}

/// jj's built-in defaults with the user's own configuration layered on top.
pub(crate) fn user_settings_for(env: &ConfigEnv) -> model::Result<UserSettings> {
    let mut config = StackedConfig::with_defaults();
    for path in config_paths(env) {
        // Skipped, not propagated — see the module comment. A broken config file costs the user
        // their settings, never their ability to read the repo.
        if let Ok(layer) = ConfigLayer::load_from_file(ConfigSource::User, path) {
            config.add_layer(layer);
        }
    }
    UserSettings::from_config(config).map_err(|e| VcsError::Io(e.to_string()))
}

/// The settings every jj-lib entry point in this crate uses.
///
/// Deliberately NOT cached. The cost is a couple of small file reads per call, which is nothing
/// beside the tree snapshot they accompany, and caching would mean a user who fixes their
/// `user.email` has to relaunch the app before the app stops writing commits without one — which is
/// the exact failure this module exists to end.
pub(crate) fn user_settings() -> model::Result<UserSettings> {
    user_settings_for(&ConfigEnv::from_process())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn temp_dir(tag: &str) -> PathBuf {
        let dir = std::env::temp_dir().join(format!("wr-cfg-{}-{}", std::process::id(), tag));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    fn write(path: &Path, body: &str) {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).unwrap();
        }
        std::fs::write(path, body).unwrap();
    }

    /// `JJ_CONFIG` REPLACES the default locations. Anything else would make it useless for the
    /// isolation the integration fixtures depend on.
    #[test]
    fn jj_config_env_var_wins_outright() {
        let dir = temp_dir("env-wins");
        let explicit = dir.join("explicit.toml");
        write(&explicit, "[user]\nname = \"X\"\n");
        write(&dir.join(".jjconfig.toml"), "[user]\nname = \"home\"\n");

        let env = ConfigEnv {
            jj_config: Some(explicit.clone()),
            home: Some(dir.clone()),
            xdg_config_home: None,
        };
        assert_eq!(config_paths(&env), vec![explicit]);
    }

    /// It can also name a directory of drop-ins.
    #[test]
    fn jj_config_may_be_a_directory() {
        let dir = temp_dir("env-dir");
        let conf = dir.join("conf");
        write(&conf.join("b.toml"), "");
        write(&conf.join("a.toml"), "");
        write(&conf.join("ignored.txt"), "");

        let env = ConfigEnv {
            jj_config: Some(conf.clone()),
            ..Default::default()
        };
        // Sorted, and non-TOML ignored.
        assert_eq!(
            config_paths(&env),
            vec![conf.join("a.toml"), conf.join("b.toml")]
        );
    }

    /// The XDG location is what `jj config path --user` reports on macOS — verified against jj 0.43.
    #[test]
    fn xdg_config_home_is_honoured() {
        let dir = temp_dir("xdg");
        let xdg = dir.join("xdg");
        let config = xdg.join("jj").join("config.toml");
        write(&config, "[user]\nname = \"X\"\n");

        let env = ConfigEnv {
            jj_config: None,
            home: Some(dir.clone()),
            xdg_config_home: Some(xdg),
        };
        assert_eq!(config_paths(&env), vec![config]);
    }

    /// With no `XDG_CONFIG_HOME`, `~/.config` is the fallback — the location jj actually uses here.
    #[test]
    fn falls_back_to_dot_config_under_home() {
        let dir = temp_dir("home-config");
        let config = dir.join(".config").join("jj").join("config.toml");
        write(&config, "[user]\nname = \"X\"\n");

        let env = ConfigEnv {
            jj_config: None,
            home: Some(dir.clone()),
            xdg_config_home: None,
        };
        assert_eq!(config_paths(&env), vec![config]);
    }

    /// `conf.d` drop-ins layer ABOVE the single file, and are sorted so precedence is reproducible
    /// across machines rather than following filesystem order.
    #[test]
    fn conf_d_dropins_come_after_the_single_file_and_are_sorted() {
        let dir = temp_dir("confd");
        let jj_dir = dir.join(".config").join("jj");
        let config = jj_dir.join("config.toml");
        write(&config, "");
        write(&jj_dir.join("conf.d").join("20-b.toml"), "");
        write(&jj_dir.join("conf.d").join("10-a.toml"), "");

        let env = ConfigEnv {
            jj_config: None,
            home: Some(dir.clone()),
            xdg_config_home: None,
        };
        assert_eq!(
            config_paths(&env),
            vec![
                config,
                jj_dir.join("conf.d").join("10-a.toml"),
                jj_dir.join("conf.d").join("20-b.toml"),
            ]
        );
    }

    #[test]
    fn nothing_configured_yields_no_paths() {
        let env = ConfigEnv::default();
        assert!(config_paths(&env).is_empty());
    }

    /// The whole point: settings built from a real file carry the user's identity, where
    /// `with_defaults()` alone yields the empty strings that get stamped onto `@`.
    #[test]
    fn settings_carry_the_users_identity() {
        let dir = temp_dir("identity");
        let config = dir.join("jjconfig.toml");
        write(
            &config,
            "[user]\nname = \"Ada Lovelace\"\nemail = \"ada@example.com\"\n",
        );

        let env = ConfigEnv {
            jj_config: Some(config),
            ..Default::default()
        };
        let settings = user_settings_for(&env).expect("settings");
        assert_eq!(settings.user_name(), "Ada Lovelace");
        assert_eq!(settings.user_email(), "ada@example.com");

        let defaults = UserSettings::from_config(StackedConfig::with_defaults()).unwrap();
        assert_eq!(defaults.user_name(), "", "the bug this replaces");
        assert_eq!(defaults.user_email(), "");
    }

    /// A malformed config must not take out the read. It costs the user their settings, not their
    /// Changes panel.
    #[test]
    fn a_broken_config_degrades_to_defaults() {
        let dir = temp_dir("broken");
        let config = dir.join("jjconfig.toml");
        write(&config, "this is not [valid toml");

        let env = ConfigEnv {
            jj_config: Some(config),
            ..Default::default()
        };
        let settings = user_settings_for(&env).expect("must still produce settings");
        assert_eq!(settings.user_name(), "");
    }
}

//! The snapshot must stamp the USER's identity onto `@`, not an empty one.
//!
//! `snapshot_working_copy` rewrites `@` whenever the working copy has moved, and jj-lib's
//! `CommitBuilder::for_rewrite_from` unconditionally sets `commit.committer = settings.signature()`.
//! While this crate built settings from `StackedConfig::with_defaults()` — whose compiled-in
//! `misc.toml` carries `user.name = ""` and `user.email = ""` — every status refresh that found a
//! change stamped an EMPTY committer onto the working-copy commit, for every jj user. Usually
//! invisible (`jj log` shows the author) and self-healing on the next real `jj` command, but not if
//! `@` is pushed as-is, which the app's Push button does via `jj git push --change @`.
//!
//! **This is its own test binary on purpose.** The fix reads `JJ_CONFIG` from the PROCESS
//! environment, so proving it end to end means setting that variable — and cargo runs the `#[test]`s
//! within a binary as parallel threads of one process, where a global env write would be visible to
//! and racing with every other test. One test, one binary, no race. The path policy itself is
//! covered deterministically by the unit tests in `src/jj_config.rs`, which take the environment as
//! a parameter and never touch the real one.

use std::path::Path;
use std::path::PathBuf;
use std::process::Command;

mod common;

fn jj(args: &[&str], dir: &Path, config: &Path) -> std::process::Output {
    Command::new("jj")
        .args(args)
        .current_dir(dir)
        .env("JJ_CONFIG", config)
        .output()
        .unwrap_or_else(|e| panic!("run jj {args:?}: {e}"))
}

/// A throwaway repo whose jj config names a distinctive identity.
fn init_repo(tag: &str) -> (PathBuf, PathBuf) {
    let dir = std::env::temp_dir().join(format!("wr-ident-{}-{}", std::process::id(), tag));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let config = dir.join("jjconfig.toml");
    std::fs::write(
        &config,
        b"[user]\nname = \"Ada Lovelace\"\nemail = \"ada@example.com\"\n",
    )
    .unwrap();
    let init = jj(&["git", "init"], &dir, &config);
    assert!(
        init.status.success(),
        "jj git init: {}",
        String::from_utf8_lossy(&init.stderr)
    );
    (dir, config)
}

/// `@`'s committer, as `name <email>`.
fn committer(dir: &Path, config: &Path) -> String {
    let out = jj(
        &[
            "log",
            "--ignore-working-copy",
            "--no-graph",
            "-r",
            "@",
            "-T",
            r#"committer.name() ++ " <" ++ committer.email() ++ ">""#,
        ],
        dir,
        config,
    );
    assert!(
        out.status.success(),
        "jj log: {}",
        String::from_utf8_lossy(&out.stderr)
    );
